package main

import (
	"fmt"
	"io"
	"os"
)

const ansiBright = "\033[38;5;255m"

// wordmark is generated by scripts/render-art.py in the main repo, so the CLI
// and the site show the same EISEN CODE art.
var wordmark = []string{
	"█▀▀ █ █▀▀ █▀▀ █▄ █   █▀▀▀ █▀▀█ █▀▀▄ █▀▀",
	"█▄▄ █ █▄▄ █▄▄ █▀▄█   █    █  █ █  █ █▄▄",
	"█▄▄ █ ▄▄█ █▄▄ █ ▀█   █▄▄▄ █▄▄█ █▄▄▀ █▄▄",
}

func printLogo(w io.Writer) {
	for _, line := range wordmark {
		left, right := line, ""
		for i := 0; i+2 < len(line); i++ {
			if line[i] == ' ' && line[i+1] == ' ' && line[i+2] == ' ' {
				left, right = line[:i], line[i+3:]
				break
			}
		}
		if right == "" {
			fmt.Fprintf(w, "%s%s%s\n", ansiGray, left, ansiReset)
			continue
		}
		fmt.Fprintf(w, "%s%s%s   %s%s%s\n", ansiGray, left, ansiReset, ansiBright, right, ansiReset)
	}
	fmt.Fprintf(w, "%s%s%s\n", ansiDim, "open models, one endpoint, your key", ansiReset)
}

func cmdLogo(asJSON bool) int {
	if asJSON {
		fmt.Printf("{\"brand\":%q,\"provider\":%q,\"version\":%q}\n", brand, "eisen", version)
		return 0
	}
	printLogo(os.Stdout)
	return 0
}
